 label='readonly global synthetic preflight';await db.connect();await owner.connect();for(const [client,role]of[[db,'staging_e2e_app'],[owner,'staging_e2e_owner']]){const r=(await client.query('SELECT current_user AS role,current_database() AS database,rolsuper,rolcreatedb,rolcreaterole,rolreplication,rolbypassrls,rolinherit FROM pg_roles WHERE rolname=current_user')).rows[0];setup(approvedRole(r,role),'Unexpected database identity/runtime authority or superuser operator.');if(role==='staging_e2e_owner')receipt.operatorCapabilities=Object.fromEntries(['rolsuper','rolcreatedb','rolcreaterole','rolreplication','rolbypassrls','rolinherit'].map(k=>[k,r[k]]));}
 setup((await db.query("SELECT has_schema_privilege(current_user,'public','CREATE') AS allowed")).rows[0].allowed===false,'Runtime cannot create public schema objects.');
 const actualPeople=(await owner.query('SELECT id,alias,name,active,is_test FROM bz_people WHERE id=ANY($1::uuid[]) OR alias=ANY($2::text[])',[people.map(x=>ids[x[0]]),people.map(x=>x[1])])).rows;setup(actualPeople.length===people.length&&people.every(([key,alias,name])=>actualPeople.some(p=>p.id===ids[key]&&p.alias===alias&&p.name===name&&p.active===true&&p.is_test===true)),'Fixed synthetic people are missing, changed or ambiguous. Release owner must reconcile; runner does not seed them.');
 const actualBusinesses=(await owner.query('SELECT id,name,active FROM bz_businesses WHERE id=ANY($1::uuid[]) OR name=ANY($2::text[])',[businesses.map(x=>ids[x[0]]),businesses.map(x=>x[1])])).rows;setup(actualBusinesses.length===businesses.length&&businesses.every(([key,name])=>actualBusinesses.some(b=>b.id===ids[key]&&b.name===name&&b.active===true)),'Fixed synthetic businesses are missing, changed or ambiguous.');
 const actualMemberships=(await owner.query('SELECT person_id,business_id,active,can_bid FROM bz_business_person_memberships WHERE person_id=ANY($1::uuid[])',[people.map(x=>ids[x[0]])])).rows;
 setup(actualMemberships.length===memberships.length&&memberships.every(([person,business])=>actualMemberships.some(m=>m.person_id===ids[person]&&m.business_id===ids[business]&&m.active&&m.can_bid)),'Fixed people have missing, conflicting or extra business-person authority.');
 const actualNetworks=(await owner.query('SELECT org_id,business_id,active FROM bz_org_business_memberships WHERE business_id=ANY($1::uuid[])',[businesses.map(x=>ids[x[0]])])).rows;
 setup(actualNetworks.length===networks.length&&networks.every(([org,business])=>actualNetworks.some(m=>m.org_id===ids[org]&&m.business_id===ids[business]&&m.active)),'Fixed businesses have missing, conflicting or extra organizer memberships.');
 const staffGrants=(await owner.query('SELECT person_id,org_id,active FROM bz_staff_grants WHERE person_id=ANY($1::uuid[])',[people.map(x=>ids[x[0]])])).rows;
 setup(staffGrants.length===2&&staffGrants.some(g=>g.person_id===ids.staff&&g.org_id===ids.saturn&&g.active)&&staffGrants.some(g=>g.person_id===ids.staffPine&&g.org_id===ids.pine&&g.active),'Fixed test people have conflicting staff authority.');
 for(const [person,business]of memberships){const r=(await owner.query('SELECT active,can_bid FROM bz_business_person_memberships WHERE person_id=$1 AND business_id=$2',[ids[person],ids[business]])).rows;setup(r.length===1&&r[0].active&&r[0].can_bid,'A fixed business-person membership is missing or changed.');}
 for(const [org,business]of networks){const r=(await owner.query('SELECT active FROM bz_org_business_memberships WHERE org_id=$1 AND business_id=$2',[ids[org],ids[business]])).rows;setup(r.length===1&&r[0].active,'A fixed organization-business membership is missing or changed.');}
 globalBefore=await globals();for(const sql of ['UPDATE bz_people SET active=false WHERE false','UPDATE bz_businesses SET active=false WHERE false','UPDATE bz_business_person_memberships SET can_bid=false WHERE false','UPDATE bz_org_business_memberships SET active=false WHERE false','UPDATE bz_event_view_grants SET active=false WHERE false','UPDATE bz_event_bidder_admissions SET access=\'BID\' WHERE false','UPDATE bz_bid_receipts SET http_status=201 WHERE false','DELETE FROM bz_manual_bids WHERE false','UPDATE bz_catalog_lots SET position=position WHERE false'])await assert.rejects(db.query(sql),e=>e.code==='42501');passed('Verified-TLS runtime/operator roles are separate; exact fixed test people/business/network memberships exist and runtime cannot modify authority or immutable history.');

 label='own API event and real immutable approval';const staff=await loginAPI('staff-saturn');const created=await request('/api/admin/events',{method:'POST',cookie:staff.cookie,json:{organizationId:ids.saturn,name:prefix,requestId:randomUUID()}});assert.equal(created.status,201);packet=created.data.draft;eventId=packet.event.id;receipt.eventId=eventId;const now=await dbNow(),opens=Math.ceil((now.getTime()+75000)/60000)*60000,closes=opens+240000;const zone=new Date(opens).toISOString().slice(0,10)===new Date(closes).toISOString().slice(0,10)?'UTC':'America/Los_Angeles',start=parts(opens,zone),end=parts(closes,zone);setup(start.date===end.date,'Generated shared window crosses its local date.');
 const event={name:prefix,eyebrow:'Synthetic manual bidding',welcome:'Welcome to this staging test.',venue:'Synthetic venue',cover:'assets/lots/cabin.jpg',date:start.date,start:start.time,end:end.time,timezone:zone,increment:INCREMENT,sponsorsEnabled:true,sponsors:[{name:'Synthetic sponsor',logo:'saturn'}]};
 const lots=['coffee','dinner','cabin'].map((image,i)=>({id:randomUUID(),title:prefix+' lot '+(i+1),short:'Synthetic selected lot',description:'Complete synthetic description '+(i+1),category:'Experiences',image:'assets/lots/'+image+'.jpg',alt:'Synthetic lot photo',opening:OPENING,includes:['Synthetic included item '+(i+1)],fine:'Staging test only.',windowId:i===1?null:'main'}));
 const saved=await request('/api/admin/events/'+eventId,{method:'PUT',cookie:staff.cookie,json:{expectedRevision:packet.revision,requestId:randomUUID(),draft:{event,lots}}});assert.equal(saved.status,200);packet=saved.data.draft;lotA=packet.lots[0].id;privateLot=packet.lots[1].id;lotB=packet.lots[2].id;const body={expectedRevision:packet.revision,requestId:randomUUID(),lotIds:[lotA,lotB]};const approved=await request('/api/admin/events/'+eventId+'/catalog-approval',{method:'POST',cookie:staff.cookie,json:body});assert.equal(approved.status,201);approval=approved.data.approval;assert.equal(approval.opensAt,new Date(opens).toISOString());assert.equal(approval.closesAt,new Date(closes).toISOString());assert.deepEqual(approval.snapshot.lots.map(l=>l.number),['01','03']);assert.deepEqual(approval.snapshot,{organization:packet.org,event,lots:[{...lots[0],number:'01',provider:packet.org},{...lots[2],number:'03',provider:packet.org}]});await assertApproval();assert.equal((await rows()).bz_catalog_approvals.length,1);assert.equal((await rows()).bz_catalog_lots.length,2);receipt.approvalId=approval.id;receipt.schedule={opensAt:approval.opensAt,closesAt:approval.closesAt};receipt.catalogSnapshotSHA256=digest(approval.snapshot);setup(opens-(await dbNow()).getTime()>15000,'Fixture setup did not leave a genuine preopening observation.');
 const owned=(await owner.query('SELECT id,org_id,created_by,draft FROM bz_events WHERE id=$1',[eventId])).rows[0];setup(owned?.org_id===ids.saturn&&owned.created_by===ids.staff&&owned.draft.name===prefix,'Refusing operator grants for any event beyond this own unique fixture.');setup((await owner.query('SELECT count(*)::int AS n FROM bz_event_view_grants WHERE event_id=$1',[eventId])).rows[0].n===0&&(await owner.query('SELECT count(*)::int AS n FROM bz_event_bidder_admissions WHERE event_id=$1',[eventId])).rows[0].n===0,'Own new event unexpectedly has audience authority.');
 const view=[ids.juniper,ids.harbor,ids.coworker,ids.viewer],bid=[[ids.juniper,'BID'],[ids.harbor,'BID'],[ids.coworker,'BID'],[ids.viewer,'VIEW'],[ids.bidOnly,'BID']];await owner.query('BEGIN');try{for(const person of view)await owner.query('INSERT INTO bz_event_view_grants(person_id,event_id,active) VALUES($1,$2,true)',[person,eventId]);for(const [person,access]of bid)await owner.query('INSERT INTO bz_event_bidder_admissions(person_id,event_id,access,active) VALUES($1,$2,$3,true)',[person,eventId,access]);await owner.query('COMMIT');}catch(e){await owner.query('ROLLBACK');throw e;}receipt.operatorWrites=[{table:'bz_event_view_grants',operation:'INSERT',eventId,people:view},{table:'bz_event_bidder_admissions',operation:'INSERT',eventId,grants:bid}];assert.deepEqual(await globals(),globalBefore);passed('Staff APIs create/save/approve one unique event and selected01+03 with a real shared minute window; only operator adds scoped VIEW/BID fixtures, leaving all globals unchanged.');

 label='scheduled authority denials';juniperAPI=await loginAPI('bidder-juniper');harborAPI=await loginAPI('bidder-harbor');coworkerAPI=await loginAPI('bidder-juniper-coworker');const scheduled=await request('/api/catalog/events/'+eventId,{cookie:juniperAPI.cookie});assert.equal(scheduled.status,200);assert.equal(scheduled.data.phase,'scheduled');assert.equal(scheduled.data.catalog,null);for(const l of packet.lots)assert.ok(!scheduled.text.includes(l.id)&&!scheduled.text.includes(l.title));const tooSoon=intent(),notOpen=await request(p(lotA).bid,{method:'POST',cookie:juniperAPI.cookie,json:tooSoon});await terminal(juniperAPI,tooSoon,notOpen,lotA,'NOT_OPEN');const sealedStanding=await request(p(lotA).standing,{cookie:juniperAPI.cookie});assert.equal(sealedStanding.status,409);sealed(sealedStanding);assert.equal(sealedStanding.data.error.code,'CATALOG_NOT_OPEN');
 for(const alias of ['staff-saturn','staff-pine','bidder-member','bidder-viewer','bidder-unlisted','bidder-pine','bidder-bid-only']){const actor=await loginAPI(alias),before=await rows();denied(await request(p(lotA).bid,{method:'POST',cookie:actor.cookie,json:intent()}));denied(await request(p(lotA).standing,{cookie:actor.cookie}));denied(await request(p(lotA).receipt(tooSoon.requestId),{cookie:actor.cookie}));assert.deepEqual(await rows(),before);}
 passed('Catalog stays hidden before SQL opening; early bid has stable durable NOT_OPEN receipt. Staff-only/member-only/VIEW-only/BID-without-VIEW/unlisted/other-tenant actors cannot bid/read/recover and no target rows change.');

 label='real opening and A context';try{browser=await chromium.launch({headless:true});}catch{throw new SetupError('Installed independent Chromium is unavailable.');}const a=await signed(),b=await signed('bidder-harbor');await expect(a.page.locator('[data-catalog-phase]')).toHaveAttribute('data-catalog-phase','scheduled');await screenshot(a,'phone-scheduled');await waitPhase('open');await expect(a.page.locator('[data-catalog-phase]')).toHaveAttribute('data-catalog-phase','open',{timeout:15000});await expect(b.page.locator('[data-catalog-phase]')).toHaveAttribute('data-catalog-phase','open',{timeout:15000});await openLot(a,lotA);await openLot(b,lotA);await expect(a.page.locator('[data-bidder-person]')).toHaveAttribute('data-bidder-person',ids.juniper);await expect(b.page.locator('[data-bidder-person]')).toHaveAttribute('data-bidder-person',ids.harbor);assert.equal(await a.frame.locator('[data-action="max-open"]:not([disabled])').count(),0);const firstStanding=await readStanding(juniperAPI,lotA);assert.equal(firstStanding.currentAmountMinor,null);assert.equal(firstStanding.minimumAmountMinor,OPENING);assert.equal(firstStanding.acceptedBidCount,0);assert.equal(firstStanding.canBid,true);const beforeOpenRetry=await rows();const notOpenReplay=await request(p(lotA).bid,{method:'POST',cookie:juniperAPI.cookie,json:tooSoon});assert.equal(notOpenReplay.status,409);assert.deepEqual(notOpenReplay.data,notOpen.data);assert.deepEqual(await rows(),beforeOpenRetry);passed('Actual retained390px A windows open on real SQL time; context is person/business specific, supported manual minimum is10000, auto-bid stays unavailable and original NOT_OPEN retry remains immutable.');

 label='A review pending accepted durability';const pendingArrived=deferred(),pendingRelease=deferred();heldReleases.push(pendingRelease.resolve);await a.page.route('**'+p(lotA).bid,async route=>{ownIntent=route.request().postDataJSON();pendingArrived.resolve();await pendingRelease.promise;await route.fallback();});const beforeReview=await rows(),dialog=await review(a,OPENING);assert.deepEqual(await rows(),beforeReview);await screenshot(a,'phone-review');const actualResponse=a.page.waitForResponse(r=>r.url().endsWith(p(lotA).bid)&&r.request().method()==='POST');const decisionBefore=await dbNow();await dialog.locator('[data-action="place"]').click();await bounded(pendingArrived.promise,'Held A reviewed bid');await expect(dialog).toHaveAttribute('data-bid-state','pending');await expect(dialog).toContainText(/Sending|not placed yet|not confirmed/i);assert.equal(await dialog.locator('.result.t-green').count(),0);assert.deepEqual(await rows(),beforeReview);await screenshot(a,'phone-pending');pendingRelease.resolve();const firstResponse=await httpPacket(await bounded(actualResponse,'Actual durable A bid201'));ownReceipt=await durable(a.actor,ownIntent,firstResponse,lotA);assert.ok(Date.parse(ownReceipt.decidedAt)>=decisionBefore.getTime()-1&&Date.parse(ownReceipt.decidedAt)<=(await dbNow()).getTime()+1);await expect(dialog).toHaveAttribute('data-bid-state','accepted');await expect(dialog).toContainText(/Bid placed|You're leading/i);await expect(dialog.locator('[data-owned-request="'+ownIntent.requestId+'"]')).toBeVisible();await assertStanding(await readStanding(a.actor,lotA),lotA,OPENING,ids.businessJuniper,1,1);await screenshot(a,'phone-accepted');await a.page.unroute('**'+p(lotA).bid);await dialog.getByRole('button',{name:'Keep browsing',exact:true}).click();passed('Actual A review writes nothing, held POST remains visibly pending without success, then201/ownedUUID and complete SQL bid/receipt/standing agree before acceptance.');

 label='offline rival and owned reload recovery';await a.frame.locator('a[href="#/lots"]').first().click();const beforeRead=await dbNow();await openLot(a,lotA);const stamp=await a.frame.locator('[data-standing-as-of]').getAttribute('data-standing-as-of');assert.ok(Date.parse(stamp)>=beforeRead.getTime()-1&&Date.parse(stamp)<=(await dbNow()).getTime());await a.context.setOffline(true);await expect(a.frame.getByRole('status').filter({hasText:/as of|out of date|stale|offline|No connection/i}).first()).toBeVisible();await expect(a.frame.locator('[data-standing-as-of]')).toHaveAttribute('data-standing-as-of',stamp);await expect(a.frame.locator('[data-action="bid"]').first()).toBeDisabled();await screenshot(a,'phone-offline');const rivalDialog=await review(b,12751,'Harbor Company','Test Harbor Bidder'),rivalHTTP=b.page.waitForResponse(r=>r.url().endsWith(p(lotA).bid)&&r.request().method()==='POST');let rivalIntent;await b.page.route('**'+p(lotA).bid,async route=>{rivalIntent=route.request().postDataJSON();await route.fallback();});await rivalDialog.locator('[data-action="place"]').click();const rivalPacket=await httpPacket(await bounded(rivalHTTP,'Harbor actual A competing201'));await durable(b.actor,rivalIntent,rivalPacket,lotA);await expect(rivalDialog).toHaveAttribute('data-bid-state','accepted');await screenshot(b,'phone-harbor-leading');await b.page.unroute('**'+p(lotA).bid);await expect(a.frame.locator('[data-standing-as-of]')).toHaveAttribute('data-standing-as-of',stamp);const afterRival=await rows();const ownReload=a.page.waitForResponse(r=>r.url().endsWith(p(lotA).receipt(ownIntent.requestId))&&r.request().method()==='GET');await a.context.setOffline(false);await a.page.reload({waitUntil:'domcontentloaded'});await openLot(a,lotA);const restored=await httpPacket(await bounded(ownReload,'A reload own receipt'));assert.equal(restored.status,200);assert.deepEqual(restored.data,{receipt:ownReceipt});await expect(a.frame.locator('.standing')).toContainText(/outbid/i);await assertStanding(await readStanding(a.actor,lotA),lotA,12751,ids.businessHarbor,2,2);assert.deepEqual(await rows(),afterRival);await screenshot(a,'phone-outbid');await a.frame.locator('.standing').scrollIntoViewIfNeeded();await expect(a.frame.locator('.standing')).toContainText(/outbid/i);await screenshot(a,'phone-outbid-standing');const empty=await signed();await openLot(empty,lotA);await assertStanding(await readStanding(empty.actor,lotA),lotA,12751,ids.businessHarbor,2,2);assert.equal(await empty.frame.locator('[data-owned-request="'+ownIntent.requestId+'"]').count(),0);await screenshot(empty,'phone-empty-browser-standing');passed('A offline snapshot retains its DB-bracketed timestamp/disabled send while actual second-user A bid12751 commits; original browser reload GETs its owned receipt and shows authoritative outbid/count2. Empty browser shares standing without fabricated individual ownership.');

 label='lost acknowledgement recovery';const current=await readStanding(a.actor,lotA),lostAmount=current.minimumAmountMinor;let lostIntent,lostResponse;const dropped=deferred();await a.page.route('**'+p(lotA).bid,async route=>{lostIntent=route.request().postDataJSON();const response=await route.fetch({headers:{...route.request().headers(),'x-vercel-protection-bypass':bypass}});lostResponse=await httpPacket(response);assert.equal(lostResponse.status,201);await route.abort('failed');dropped.resolve();});const lostDialog=await review(a,lostAmount);await lostDialog.locator('[data-action="place"]').click();await bounded(dropped.promise,'Durable bid lost acknowledgement');await unconfirmed(lostDialog);const lostReceipt=await durable(a.actor,lostIntent,lostResponse,lotA);await screenshot(a,'phone-unconfirmed-committed');const beforeLookup=await rows(),lookup=a.page.waitForResponse(r=>r.url().endsWith(p(lotA).receipt(lostIntent.requestId))&&r.request().method()==='GET');await lostDialog.getByRole('button',{name:'Check status',exact:true}).click();const looked=await httpPacket(await bounded(lookup,'Original lost UUID lookup'));assert.equal(looked.status,200);assert.deepEqual(looked.data,{receipt:lostReceipt});await expect(lostDialog).toHaveAttribute('data-bid-state','accepted');assert.deepEqual(await rows(),beforeLookup);await screenshot(a,'phone-recovered');await a.page.unroute('**'+p(lotA).bid);await lostDialog.getByRole('button',{name:'Keep browsing',exact:true}).click();passed('After actual201 commits but transport acknowledgement is dropped, A remains unconfirmed; Check status GETs the originalUUID and restores exact durable acceptance without a second bid or standing mutation.');

 label='abort-before stable retry and received rejection';await rivalDialog.getByRole('button',{name:'Keep browsing',exact:true}).click();await refreshLot(b,lotA);const next=(await readStanding(b.actor,lotA)).minimumAmountMinor,attempts=[];let attemptCount=0;await b.page.route('**'+p(lotA).bid,async route=>{attempts.push(route.request().postDataJSON());if(++attemptCount===1)return route.abort('failed');return route.fallback();});const beforeAbort=await rows(),retryDialog=await review(b,next,'Harbor Company','Test Harbor Bidder');await retryDialog.locator('[data-action="place"]').click();await unconfirmed(retryDialog);assert.deepEqual(await rows(),beforeAbort);const noReceipt=b.page.waitForResponse(r=>r.url().endsWith(p(lotA).receipt(attempts[0].requestId))&&r.request().method()==='GET');await retryDialog.getByRole('button',{name:'Check status',exact:true}).click();denied(await httpPacket(await bounded(noReceipt,'Unsent UUID absent receipt')),[404]);await notRecorded(retryDialog);assert.deepEqual(await rows(),beforeAbort);await screenshot(b,'phone-not-recorded');const retryHTTP=b.page.waitForResponse(r=>r.url().endsWith(p(lotA).bid)&&r.request().method()==='POST');await retryDialog.getByRole('button',{name:'Try again',exact:true}).click();const retryResult=await httpPacket(await bounded(retryHTTP,'Same unsent intent retry201'));assert.deepEqual(attempts[0],attempts[1]);await durable(b.actor,attempts[0],retryResult,lotA);await expect(retryDialog).toHaveAttribute('data-bid-state','accepted');await b.page.unroute('**'+p(lotA).bid);await retryDialog.getByRole('button',{name:'Keep browsing',exact:true}).click();await refreshLot(a,lotA);const staleAmount=(await readStanding(a.actor,lotA)).minimumAmountMinor,staleDialog=await review(a,staleAmount);const coworkerIntent=intent(ids.businessJuniper,staleAmount),coworkerResult=await request(p(lotA).bid,{method:'POST',cookie:coworkerAPI.cookie,json:coworkerIntent});await durable(coworkerAPI,coworkerIntent,coworkerResult,lotA);let staleIntent;await a.page.route('**'+p(lotA).bid,async route=>{staleIntent=route.request().postDataJSON();await route.fallback();});const staleHTTP=a.page.waitForResponse(r=>r.url().endsWith(p(lotA).bid)&&r.request().method()==='POST');await staleDialog.locator('[data-action="place"]').click();const stalePacket=await httpPacket(await bounded(staleHTTP,'Actual stale reviewed409'));await terminal(a.actor,staleIntent,stalePacket,lotA,'UNSUPPORTED_SELF_RAISE');await expect(staleDialog).toHaveAttribute('data-bid-state','rejected');assert.equal(await staleDialog.locator('.result.t-green').count(),0);await screenshot(a,'phone-rejected');await a.page.unroute('**'+p(lotA).bid);await staleDialog.getByRole('button',{name:'Keep browsing',exact:true}).click();passed('Abort-before creates no bid/receipt; Check status confirms absence and Try again retains identical original intent. Another same-business person can commit; real terminal409 stays visibly rejected without fabricated owned success.');

 label='current authority foreign receipt typed claims';const deniedBefore=await rows();denied(await request(p(lotA).receipt(ownIntent.requestId),{cookie:harborAPI.cookie}),[403,404]);for(const body of [{...intent(ids.businessPine,50000)},{...intent(ids.businessJuniper,50000),memberId:'SATURN-APPROVED',personId:ids.juniper,role:'BID',accepted:true}]){const r=await request(p(lotA).bid,{method:'POST',cookie:harborAPI.cookie,json:body,headers:{'x-person-id':ids.juniper,'x-role':'BID','x-member-id':'SATURN-APPROVED'}});assert.ok([400,403,404].includes(r.status));sealed(r);assert.equal(r.data.receipt,undefined);}for(const lot of [privateLot,randomUUID()]){denied(await request(p(lot).bid,{method:'POST',cookie:juniperAPI.cookie,json:intent()}),[403,404]);const r=await request('/api/catalog/events/'+eventId+'/lots/'+lot,{cookie:juniperAPI.cookie});assert.equal(r.status,404);sealed(r);}assert.deepEqual(await rows(),deniedBefore);assert.deepEqual(await globals(),globalBefore);passed('Another actor cannot recover owned receipt, business/person/member/header claims cannot grant authority, and unselected/unknown lots remain opaque; all scoped SQL and global authority stay unchanged.');

 label='two-business equal race plus same-person duplicate';const equal=[intent(ids.businessJuniper,OPENING),intent(ids.businessHarbor,OPENING)],raceActors=[juniperAPI,harborAPI];
 const race=await Promise.all(equal.map((body,i)=>request(p(lotB).bid,{method:'POST',cookie:raceActors[i].cookie,json:body})));
 assert.deepEqual(race.map(r=>r.status).sort(),[201,409]);const winner=race.findIndex(r=>r.status===201);
 await durable(raceActors[winner],equal[winner],race[winner],lotB);await terminal(raceActors[1-winner],equal[1-winner],race[1-winner],lotB,'BELOW_MINIMUM');
 await assertStanding(await readStanding(juniperAPI,lotB),lotB,OPENING,equal[winner].businessId,1,1);
 const beforeRaceReplay=await rows();for(let i=0;i<2;i++){const replay=await request(p(lotB).bid,{method:'POST',cookie:raceActors[i].cookie,json:equal[i]});assert.equal(replay.status,race[i].status);assert.deepEqual(replay.data.receipt,race[i].data.receipt);}assert.deepEqual(await rows(),beforeRaceReplay);
 const duplicateActor=raceActors[1-winner],duplicate=intent(equal[1-winner].businessId,12500),duplicates=await Promise.all([request(p(lotB).bid,{method:'POST',cookie:duplicateActor.cookie,json:duplicate}),request(p(lotB).bid,{method:'POST',cookie:duplicateActor.cookie,json:duplicate})]);
 assert.deepEqual(duplicates.map(r=>r.status),[201,201]);assert.deepEqual(duplicates[0].data.receipt,duplicates[1].data.receipt);await durable(duplicateActor,duplicate,duplicates[0],lotB);
 await assertStanding(await readStanding(juniperAPI,lotB),lotB,12500,duplicate.businessId,2,2);
